+#!/usr/bin/env node
+import { existsSync, readFileSync, writeFileSync } from 'node:fs';
+const args = process.argv.slice(2);
+const command = args[0];
+const val = (n) => {
+  const i = args.indexOf(`--${n}`);
+  return i >= 0 ? args[i + 1] : null;
+};
+const file = val('file') ?? '.zeus/run-state.json';
+const transitions = {
+  intake: ['compiled', 'blocked', 'failed'],
+  compiled: ['evidence_ready', 'blocked', 'failed'],
+  evidence_ready: ['planned', 'blocked', 'failed'],
+  planned: ['branch_ready', 'implementing', 'blocked', 'failed'],
+  branch_ready: ['implementing', 'blocked', 'failed'],
+  implementing: ['local_green', 'blocked', 'failed'],
+  local_green: ['review_green', 'pr_open', 'closed', 'blocked', 'failed'],
+  review_green: ['pr_open', 'closed', 'blocked', 'failed'],
+  pr_open: ['ci_running', 'blocked', 'failed'],
+  ci_running: ['ci_green', 'blocked', 'failed'],
+  ci_green: ['merge_authorized', 'blocked', 'failed'],
+  merge_authorized: ['merged', 'blocked', 'failed'],
+  merged: ['deployment_running', 'closed', 'blocked', 'failed'],
+  deployment_running: ['production_verified', 'rolled_back', 'incident_open', 'blocked', 'failed'],
+  production_verified: ['closed', 'incident_open'],
+  incident_open: ['rolled_back', 'production_verified', 'closed', 'failed'],
+  rolled_back: ['closed', 'incident_open'],
+  blocked: [],
+  failed: [],
+  closed: [],
+};
+const load = () => JSON.parse(readFileSync(file, 'utf8'));
+const save = (s) => writeFileSync(file, JSON.stringify(s, null, 2) + '\n', 'utf8');
+if (command === 'init') {
+  if (existsSync(file) && !args.includes('--force')) {
+    console.error('State file exists; use --force');
+    process.exit(1);
+  }
+  const s = {
+    runId: val('run-id') ?? `zeus-${Date.now()}`,
+    state: 'intake',
+    outcome: val('outcome') ?? '',
+    branch: null,
+    baseSha: null,
+    headSha: null,
+    pr: null,
+    mergedSha: null,
+    deployedSha: null,
+    evidence: [],
+    blockers: [],
+  };
+  save(s);
+  console.log(JSON.stringify(s, null, 2));
+} else if (command === 'transition') {
+  const s = load(),
+    next = val('state');
+  if (!next || !(transitions[s.state] ?? []).includes(next)) {
+    console.error(`Invalid transition ${s.state} -> ${next}`);
+    process.exit(1);
+  }
+  s.state = next;
+  save(s);
+  console.log(JSON.stringify(s, null, 2));
+} else if (command === 'evidence') {
+  const s = load(),
+    status = val('status'),
+    kind = val('kind');
+  if (!kind || !['pass', 'fail', 'unknown', 'not-applicable'].includes(status)) {
+    console.error('Use --kind and valid --status');
+    process.exit(2);
+  }
+  s.evidence.push({ kind, status, source: val('source') ?? '', details: val('details') ?? '' });
+  save(s);
+  console.log(JSON.stringify(s, null, 2));
+} else if (command === 'show') {
+  console.log(JSON.stringify(load(), null, 2));
+} else {
+  console.error('Usage: zeus-run-state init|transition|evidence|show --file path ...');
+  process.exit(2);
+}

